export const LITE_REVIEW_STATS: ReviewStats = {"total_reviews":142,"average_rating":4.9,"five_star_count":142,"four_star_count":0,"license":"Est. 2005 • Insured Oahu Specialists","waipahu_shop_address":"94-150 Leoleo St #203, Waipahu, HI 96797","top_neighborhoods":[{"name":"Waipahu","count":17},{"name":"Honolulu","count":16},{"name":"Ewa Beach","count":17},{"name":"Kailua","count":16},{"name":"Pearl City","count":15},{"name":"Mililani","count":16},{"name":"Aiea","count":16},{"name":"Kapolei","count":14}],"top_technicians":["Brian","Chris","Omar","Rostin","Makoa","Matt","Scott"]};

export const LITE_SHOWCASE_REVIEWS: Review[] = SHOWCASE_IDS.map(hydrate);

export function getLiteReviewStats(): ReviewStats {
    return LITE_REVIEW_STATS;
}

export function getLiteReviews(): Review[] {
    return LITE_SHOWCASE_REVIEWS;
}

export function getLiteProductReviews(productId: number, limit: number = 3): Review[] {
    const ids = PRODUCT_IDS_MAP[productId] || SHOWCASE_IDS;
    return ids.slice(0, limit).map(hydrate);
}
